// services/ai-i18n.ts: translates English AI astrologer responses into
// Hindi, Marathi, and Tamil. Uses the same i18n translations for zodiac
// and planet names so output stays consistent with the rest of the app.

import { translations, type Language } from '@/i18n/translations';
import type { ZodiacSign, PlanetName } from '@/types';

type TranslationTree = typeof translations.en;

// ─── Name lookups (from i18n) ─────────────────────────────────────────────────

function tr(lang: Language): TranslationTree {
  return translations[lang];
}

function translateZodiacName(sign: ZodiacSign, lang: Language): string {
  if (lang === 'en') return sign;
  return tr(lang).zodiac[sign] ?? sign;
}

function translatePlanetName(planet: string, lang: Language): string {
  if (lang === 'en') return planet;
  const key = planet as keyof TranslationTree['planets'];
  return tr(lang).planets[key] ?? planet;
}

// ─── Phrase dictionary ─────────────────────────────────────────────────────────
// Each English phrase maps to its translation in each language.
// We use longest-match-first so multi-word phrases are replaced before
// individual words.

interface PhraseEntry {
  en: string;
  hi?: string;
  mr?: string;
  ta?: string;
}

