// ─── Translation engine ───────────────────────────────────────────────────────

function translatePhrases(text: string, lang: Language): string {
  if (lang === 'en') return text;

  // Sort by length descending so longer phrases match first
  const sorted = [...PHRASES].sort((a, b) => b.en.length - a.en.length);
  let result = text;

  for (const phrase of sorted) {
    const translation = phrase[lang];
    if (!translation) continue;
    // Escape regex special characters in the English phrase
    const escaped = phrase.en.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    // Use word boundaries for short phrases to avoid partial matches
    // For phrases that start/end with word characters, add \b
    const startsWithWord = /^\w/.test(phrase.en);
    const endsWithWord = /\w$/.test(phrase.en);
    const prefix = startsWithWord ? '\\b' : '';
    const suffix = endsWithWord ? '\\b' : '';
    result = result.replace(new RegExp(prefix + escaped + suffix, 'g'), translation);
  }

  return result;
}

function translateZodiacAndPlanets(text: string, lang: Language): string {
  if (lang === 'en') return text;

  const zodiacSigns: ZodiacSign[] = [
    'Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo',
    'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', 'Pisces',
  ];
  const planetNames: PlanetName[] = ['Sun', 'Moon', 'Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn'];

  let result = text;

  // Translate zodiac signs (longest first to avoid partial matches)
  for (const sign of zodiacSigns.sort((a, b) => b.length - a.length)) {
    const translated = translateZodiacName(sign, lang);
    if (translated !== sign) {
      result = result.replace(new RegExp(`\\b${sign}\\b`, 'g'), translated);
    }
  }

  // Translate planet names
  for (const planet of planetNames.sort((a, b) => b.length - a.length)) {
    const translated = translatePlanetName(planet, lang);
    if (translated !== planet) {
      result = result.replace(new RegExp(`\\b${planet}\\b`, 'g'), translated);
    }
  }

  return result;
}

export function translateAIResponse(text: string, lang: Language): string {
  if (lang === 'en') return text;
  // First translate phrases, then zodiac/planet names
  // Phrases first because some phrases contain planet/sign names that
  // would break the phrase match if translated first
  let result = translatePhrases(text, lang);
  result = translateZodiacAndPlanets(result, lang);
  return result;
}
